using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class ArmyRoadTests
{
    internal static WorldSession Start(){var seed=NpcFreightTests.Start().DiagnosticSnapshot().NewGame!;var s=new WorldSession(NewGameWorld.Create(seed.Start,seed.Registered,seed.Selected.Value,1,NewGameWorld.CompactPersonalAuthority,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,voyageRules:VoyageExpense.Standard,economyPolicy:ArmyRoadMarch.Policy));Send(s,NewMilitaryAction.Request);Advance(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Accept);Advance(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Pickup);return s;}
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void Advance(WorldSession s,long to){while(s.Seconds<to){var old=s.Seconds;s.SetPaused(false);s.AdvanceTo(to,100000);Assert.True(s.Seconds>old);}}
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Good(s.Open(s.PlayerControl,m.Id,s.Revision));}
    static void Send(WorldSession s,NewMilitaryAction a,long n=0){var w=s.DiagnosticSnapshot();Good(s.DecideNewMilitary(new NewMilitaryInput(new("request:road-mil/"+s.Revision),a,n){AuthorityPolicy=a==NewMilitaryAction.Request?NewGameMilitary.AuthorityContract:null,LedgerPolicy=a==NewMilitaryAction.Request?NewGameMilitary.LedgerIdentityContract:null,FromLedger=a==NewMilitaryAction.Request?NewGameMilitary.SourceForCurrentHouse(w):null,CycleContract=a==NewMilitaryAction.Request?NewGameMilitary.CycleForCurrentHouse(w):null},s.PlayerControl,s.Revision));}
    static void Load(WorldSession s){var v=s.MilitaryEconomyView()!;Good(s.ManageMilitaryRice(new(new("request:road-load-source"),v.Depot,120),s.PlayerControl,s.Revision));Send(s,NewMilitaryAction.Load,NewGameMilitary.Capacity);}
    static EntityId Near(WorldSession s){var w=s.DiagnosticSnapshot();var rows=new List<(EntityId Site,long Time)>();foreach(var n in BranchRoutes.GraphNodes(w).Where(n=>n.Id!=TravelWorld.Origin(w,s.PlayerControl)&&MaterialMarkets.Sites(w).Contains(RegionalCampaign.Site(n.Id)))){try{rows.Add((RegionalCampaign.Site(n.Id),TravelWorld.Move(w,"request:road-plan",n.Id,true).WorkSeconds));}catch(InvalidDataException){}}return rows.OrderBy(q=>q.Time).First().Site;}
    static CommandResult March(WorldSession s,EntityId to)=>s.ManageArmyRoad(new(new("request:road/"+s.Revision),ArmyRoadAction.March,to),s.PlayerControl,s.Revision);
    [Fact]public void RoadMarchKeepsSameArmyConsumesRealFoodAndReachesActualNode(){var s=Start();Load(s);var before=s.DiagnosticSnapshot();var army=before.NewMilitary!.Terms.Army;var home=before.NewMilitary.Terms.Site;var to=Near(s);Good(March(s,to));Advance(s,s.Seconds+3);var w=s.DiagnosticSnapshot();Assert.Equal(army,w.NewMilitary!.Terms.Army);Assert.Equal(home,w.NewMilitary.Terms.Site);Assert.True(ArmyRoadMarch.Active(w));Assert.True(NewGameMilitary.View(w).Carry<NewGameMilitary.Capacity);var j=w.Branches!.Journeys.Last();Advance(s,j.Legs[^1].EndAt+2);w=s.DiagnosticSnapshot();Assert.False(ArmyRoadMarch.Active(w));Assert.Equal(to,s.ArmyRoadView()!.Assembly);Assert.Equal(to,w.Locations.Single(l=>l.Actor==s.PlayerControl).Site);Assert.Equal(ArmyRoadMarch.AssemblyPoint(w,0,s.Seconds),NewGameMilitary.Position(w,0,s.Seconds));Assert.Equal(ContractJson.Write(w),ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(w))).DiagnosticSnapshot()));}
    [Fact]public void MissingFoodRejectsMarchAtomically(){var s=Start();var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,March(s,Near(s)).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}

    static void Arrive(WorldSession s){Advance(s,s.Seconds+2);var j=s.DiagnosticSnapshot().Branches!.Journeys.Last();Advance(s,j.Legs[^1].EndAt+2);}
    static void Out(WorldSession s){Load(s);Good(March(s,Near(s)));Arrive(s);}
    [Fact]public void ArrivalCanDeployRegatherAndReturnSameLoanHome(){var s=Start();Out(s);var foreign=s.ArmyRoadView()!.Assembly;Send(s,NewMilitaryAction.Deploy);var anchor=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Good(s.DecideNewMilitary(new(new("request:foreign-formation"),NewMilitaryAction.Form,0,new(anchor.X+30000,anchor.Y-10000),new(anchor.X+30000,anchor.Y+10000)),s.PlayerControl,s.Revision));Advance(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.Max(r=>r.LastOrDefault()?.EndAt??s.Seconds)+2);Assert.NotEqual(ArmyRoadMarch.AssemblyPoint(s.DiagnosticSnapshot(),0,s.Seconds),NewGameMilitary.Position(s.DiagnosticSnapshot(),0,s.Seconds));Send(s,NewMilitaryAction.Recall);Advance(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Max(o=>o.Routes.Max(p=>p.LastOrDefault()?.EndAt??s.Seconds))+2);Send(s,NewMilitaryAction.Enter);Assert.Equal(foreign,s.ArmyRoadView()!.Assembly);Good(March(s,new("site:castle")));Arrive(s);Send(s,NewMilitaryAction.Unload,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);Send(s,NewMilitaryAction.Report);Advance(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Return);Advance(s,s.Seconds+2);Open(s);Assert.False(NewGameMilitary.View(s.DiagnosticSnapshot()).Custody);}
    [Fact]public void InForeignAssemblyWaitingConsumesButHomeWaitingDoesNot(){var s=Start();Load(s);var before=NewGameMilitary.View(s.DiagnosticSnapshot()).Carry;Advance(s,s.Seconds+10);Assert.Equal(before,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);Good(March(s,Near(s)));Arrive(s);before=NewGameMilitary.View(s.DiagnosticSnapshot()).Carry;Advance(s,s.Seconds+10);Assert.Equal(before-1000,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);}
    [Fact]public void PurchaseUsesOwnCashFiniteMarketAndIsIdempotent(){var s=Start();Out(s);var v=s.ArmyRoadView()!;Assert.NotNull(v.LocalRicePrice);var input=new ArmyRoadInput(new("request:road-buy"),ArmyRoadAction.BuyRice,RiceKg:1);long carry=NewGameMilitary.View(s.DiagnosticSnapshot()).Carry;Good(s.ManageArmyRoad(input,s.PlayerControl,s.Revision));Assert.Equal(carry+MilitaryEconomy.PersonSecondsPerKg,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);var after=s.ArmyRoadView()!;Assert.Equal(v.PrivateMoney-v.LocalRicePrice,after.PrivateMoney);Assert.Equal(v.LocalFreeRice-1,after.LocalFreeRice);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.ManageArmyRoad(input,s.PlayerControl,0).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.IdPayloadConflict,s.ManageArmyRoad(input with{RiceKg=2},s.PlayerControl,s.Revision).Code);}
    [Theory][InlineData(0)][InlineData(-1)][InlineData(121)]public void InvalidRiceDoesNotAlterWorld(long kg){var s=Start();var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageArmyRoad(new(new("request:bad-rice"),ArmyRoadAction.BuyRice,RiceKg:kg),s.PlayerControl,s.Revision).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void CapacityPreventsBuyingAtFullCarry(){var s=Start();Load(s);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageArmyRoad(new(new("request:overfill"),ArmyRoadAction.BuyRice,RiceKg:1),s.PlayerControl,s.Revision).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void CannotDuplicateMarchWhileMoving(){var s=Start();Load(s);var input=new ArmyRoadInput(new("request:unique-road"),ArmyRoadAction.March,Near(s));Good(s.ManageArmyRoad(input,s.PlayerControl,s.Revision));Assert.Equal(ResultCode.AlreadyAccepted,s.ManageArmyRoad(input,s.PlayerControl,0).Code);Advance(s,s.Seconds+2);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,March(s,new("site:castle")).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)]public void ActualSaveRecoveryKeepsRoadAssemblyFoodAndFuture(int phase){var a=Start();Load(a);Good(March(a,Near(a)));if(phase==1)Advance(a,a.Seconds+2);if(phase==5){var closed=a.DiagnosticSnapshot();closed.Couriers=closed.Couriers! with{Conditions=BranchRoutes.GraphEdges(closed).Where(e=>e.From=="castle"||e.To=="castle").Select(e=>new RoadCondition(closed.ElapsedSeconds+1,e.Id,true)).ToArray()};a=new WorldSession(closed);Advance(a,a.Seconds+2);}else if(phase>=2)Arrive(a);if(phase==6){Good(March(a,new("site:castle")));Arrive(a);}if(phase is 3 or 4){Good(a.ManageArmyRoad(new(new("request:recover-buy"),ArmyRoadAction.BuyRice,RiceKg:1),a.PlayerControl,a.Revision));if(phase==4)Send(a,NewMilitaryAction.Deploy);}a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"army-road-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"road",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("road"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(w),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(a.ArmyRoadView()),ContractJson.Write(b.ArmyRoadView()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"army-road-"+phase+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,"army-road-"+phase+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}foreach(var q in new[]{a,b})Advance(q,q.Seconds+10);Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));}

    [Fact]public void UnknownClosureDoesNotChangePlanBeforePhysicalEntry(){var a=Start();Load(a);var to=Near(a);var w=a.DiagnosticSnapshot();var edges=BranchRoutes.GraphEdges(w).Where(e=>e.From=="castle"||e.To=="castle").Select(e=>e.Id).ToArray();w.Couriers=w.Couriers! with{Conditions=edges.Select(e=>new RoadCondition(w.ElapsedSeconds+1,e,true)).ToArray()};var b=new WorldSession(w);Good(March(a,to));Good(March(b,to));Assert.Equal(a.DiagnosticSnapshot().ArmyRoad!.Entries[0].Terms!.Intent,b.DiagnosticSnapshot().ArmyRoad!.Entries[0].Terms!.Intent);Assert.Empty(BranchRoutes.KnownBlocked(b.DiagnosticSnapshot(),b.PlayerControl));Advance(b,b.Seconds+2);Assert.Equal("road-unavailable",b.DiagnosticSnapshot().Tasks.Last().InternalReason);Assert.Equal(new EntityId("site:castle"),b.ArmyRoadView()!.Assembly);Assert.NotEmpty(BranchRoutes.KnownBlocked(b.DiagnosticSnapshot(),b.PlayerControl));var saved=ContractJson.Write(b.DiagnosticSnapshot());Assert.Equal(saved,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(saved)).DiagnosticSnapshot()));}
    [Fact]public void RedirectedLongJourneyStopsAtRealNodeBeforeUnfundedEdge(){var s=Start();Load(s);Good(March(s,Near(s)));Advance(s,s.Seconds+2);Good(s.ChangeTravel(TravelControl.Request(s.DiagnosticSnapshot(),"request:army-redirect","edo"),s.Revision));var d=s.DiagnosticSnapshot().TravelDecisions!.Last();Advance(s,d.EffectiveAt+2);var w=s.DiagnosticSnapshot();while(!w.TrafficStops!.Any(t=>t.Reason==ArmyRoadMarch.FoodStop)&&ArmyRoadMarch.Active(w)){var j=w.Branches!.Journeys.Last();var next=j.Legs.Where(l=>l.EndAt>s.Seconds).FirstOrDefault()?.EndAt??s.Seconds+2;Advance(s,next+1);w=s.DiagnosticSnapshot();}var stop=Assert.Single(w.TrafficStops!,t=>t.Reason==ArmyRoadMarch.FoodStop);Assert.Equal(RegionalCampaign.Site(stop.Node),w.Locations.Single(l=>l.Actor==s.PlayerControl).Site);Assert.Equal(ArmyRoadMarch.AssemblyPoint(w,0,s.Seconds),NewGameMilitary.Position(w,0,s.Seconds));Assert.True(NewGameMilitary.View(w).Carry>=0);var saved=ContractJson.Write(w);Assert.Equal(saved,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(saved)).DiagnosticSnapshot()));}
    [Fact]public void PreparedMarchPublishesOnceAndRejectsStaleSource(){var a=Start();Load(a);var host=new WorldSessionHost(a);var input=new ArmyRoadInput(new("request:prepared-road"),ArmyRoadAction.March,Near(a));var capture=a.CaptureArmyRoad(input,a.Revision);var prepared=capture.Prepare();Assert.Empty(a.DiagnosticSnapshot().ArmyRoad!.Entries);Assert.Equal(ResultCode.Accepted,host.CommitSubmit(prepared,out var published));Assert.Equal(ResultCode.Accepted,published!.Result.Code);Assert.Equal(ResultCode.StateChanged,host.CommitSubmit(prepared,out _));Assert.Single(host.Current.DiagnosticSnapshot().ArmyRoad!.Entries);var stale=host.Current.CaptureArmyRoad(new(new("request:stale-rice"),ArmyRoadAction.BuyRice,RiceKg:1),host.Current.Revision).Prepare();host.Current.SetPaused(false);Assert.Equal(ResultCode.StateChanged,host.CommitSubmit(stale,out _));}
    [Fact]public void CanceledPreparedMarchCannotPublish(){var a=Start();Load(a);var host=new WorldSessionHost(a);using var cancel=new CancellationTokenSource();var candidate=a.CaptureArmyRoad(new(new("request:cancel-prepared"),ArmyRoadAction.March,Near(a)),a.Revision).Prepare(cancel.Token);cancel.Cancel();Assert.Equal(ResultCode.NotAvailable,host.CommitSubmit(candidate,out _));Assert.Empty(a.DiagnosticSnapshot().ArmyRoad!.Entries);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ForgedArmyOwnerSourceOrRicePriceIsRejected(int kind){var s=Start();Out(s);Good(s.ManageArmyRoad(new(new("request:tamper-buy"),ArmyRoadAction.BuyRice,RiceKg:1),s.PlayerControl,s.Revision));var w=s.DiagnosticSnapshot();var es=w.ArmyRoad!.Entries.ToArray();if(kind==2)es[^1]=es[^1] with{Purchase=es[^1].Purchase! with{UnitPrice=0}};else es[0]=es[0] with{Terms=kind==0?es[0].Terms! with{Army=new("army:missing")}:es[0].Terms! with{Source=new("site:kofu")}};w.ArmyRoad=w.ArmyRoad with{Entries=es};Assert.ThrowsAny<Exception>(()=>new WorldSession(w));}
    [Fact]public void OldV15HasNoNewFieldsAndCannotMarch(){var seed=NpcFreightTests.Start().DiagnosticSnapshot().NewGame!;var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"army-normal-"+Guid.NewGuid().ToString("N")));var profile=store.New(seed.Start,seed.Registered,seed.Selected.Value,1,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.Policy,LocalInspectionFindings.Policy,WorkFollowup.Policy,null,VoyageExpense.Standard,NpcArmies.CompactCombatPolicy,ArmyRoadMarch.Policy,PersonalCompanions.RetainerReleasePolicy,TruceNegotiations.Policy,PrivateInformation.Policy,PrivateStanddown.Policy);var normal=new WorldSession(NewCampaignStore.Build(store.Read(profile.Instance)));Assert.NotNull(normal.DiagnosticSnapshot().ArmyRoad);var s=FieldConvoyTests.Start();var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("ArmyRoad",System.Text.Encoding.UTF8.GetString(bytes));Assert.Equal(ResultCode.NotAvailable,s.ManageArmyRoad(new(new("request:old-road"),ArmyRoadAction.March,new("site:fork")),s.PlayerControl,s.Revision).Code);Assert.Equal(bytes,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(bytes)).DiagnosticSnapshot()));}

    [Fact]public void LargeAndSmallClockStepsHaveIdenticalRoadFood(){var a=Start();Load(a);Good(March(a,Near(a)));var b=new WorldSession(a.DiagnosticSnapshot());Advance(a,a.Seconds+10);for(int n=0;n<10;n++)Advance(b,b.Seconds+1);var x=a.DiagnosticSnapshot();var y=b.DiagnosticSnapshot();Assert.Equal(NewGameMilitary.View(x).Carry,NewGameMilitary.View(y).Carry);Assert.Equal(ContractJson.Write(x.ArmyRoad!.Uses),ContractJson.Write(y.ArmyRoad!.Uses));Assert.Equal(ContractJson.Write(x.Branches!.Journeys),ContractJson.Write(y.Branches!.Journeys));foreach(var n in Enumerable.Range(0,3))Assert.Equal(NewGameMilitary.Position(x,n,a.Seconds),NewGameMilitary.Position(y,n,b.Seconds));}
    [Fact]public void WrongHistoricalStrengthCannotForgeConsumption(){var s=Start();Load(s);Good(March(s,Near(s)));Advance(s,s.Seconds+4);var w=s.DiagnosticSnapshot();var use=w.ArmyRoad!.Uses[0];w.ArmyRoad=w.ArmyRoad with{Uses=[use with{Use=use.Use with{Soldiers=use.Use.Soldiers+1}}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void MovingArmyCannotBuyRemoteRice(){var s=Start();Load(s);Good(March(s,Near(s)));Advance(s,s.Seconds+2);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageArmyRoad(new(new("request:remote-rice"),ArmyRoadAction.BuyRice,RiceKg:1),s.PlayerControl,s.Revision).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}

    [Fact]public void LaterLearnedOldObservationCannotBeForgedIntoPastPlan(){var a=Start();Out(a);var w=a.DiagnosticSnapshot();var origin=TravelWorld.Origin(w,w.PlayerControl);var path=BranchRoutes.Plan(origin,"castle",[],w:w);var edge=BranchRoutes.GraphEdges(w).First(e=>(e.From==origin||e.To==origin)&&!path.Contains(e.Id)&&!NationalRoutes.Sea(e.Id)).Id;w.Couriers=w.Couriers! with{Conditions=[..w.Couriers.Conditions,new(w.ElapsedSeconds,edge,true)]};w.Branches=w.Branches! with{BlockedEdges=[..w.Branches.BlockedEdges,edge]};RegionalCampaign.InspectRoad(w,w.PlayerControl,edge);var id=w.Evidence.Last(e=>e.Claim=="route-block:"+edge).Id;a=new WorldSession(w);Good(March(a,new("site:castle")));Advance(a,a.Seconds+2);w=a.DiagnosticSnapshot();w.Knowledge=w.Knowledge.Select(k=>k.Evidence==id?k with{LearnedAt=w.ElapsedSeconds}:k).ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
}
